var EXTRA=[{"dot": "gray", "j": "Arthrosc Tech", "h": "Radice meniscale più osteotomia tibiale alta: pianificazione e guide su misura", "v": "Nota tecnica iraniana su due tue procedure insieme, tunnel transtibiale e osteotomia, con pianificazione TC e guide stampate; nessun esito clinico.", "pmid": "42889858", "doi": "10.1002/atn2.70323", "temi": ["radice meniscale", "osteotomia tibiale alta", "guide stampate", "pianificazione"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Avulsione dell'eminenza tibiale: fissazione artroscopica con compressione circonferenziale", "v": "Nota tecnica indiana su una lesione rara; descrive la procedura, nessun dato su pazienti o esiti nell'abstract.", "pmid": "42890472", "doi": "10.1002/atn2.70311", "temi": ["LCA", "avulsione", "eminenza tibiale", "tecnica artroscopica"]}, {"dot": "gray", "j": "JBI Evid Synth", "h": "Chinesiofobia dopo il LCA: mappa di una letteratura frammentata", "v": "Revisione di scoping: pochi studi di intervento, adolescenti e donne poco rappresentati; è una mappa, non una stima di effetto.", "pmid": "42873955", "doi": "10.11124/JBIES-26-00001", "temi": ["LCA", "chinesiofobia", "riabilitazione", "rientro allo sport"]}, {"dot": "gray", "j": "JSAMS Plus", "h": "LCA nel calcio femminile d'élite: più rotture nei primi mesi della stagione", "v": "Analisi retrospettiva di dati pubblici di terze parti; il ruolo in campo non cambia il rischio, il limite è la fonte mediatica degli infortuni.", "pmid": "42830809", "doi": "10.1016/j.jsampl.2026.100159", "temi": ["LCA", "calcio femminile", "prevenzione", "stagione"]}, {"dot": "gray", "j": "J Pediatr Soc North Am", "h": "Ciclo mestruale e meccanica del ginocchio nelle adolescenti: differenze fra le fasi", "v": "Studio di laboratorio su atlete adolescenti in un compito di cambio di direzione; misura la biomeccanica, non le rotture: non dice nulla sul rischio reale.", "pmid": "42890200", "doi": "10.1016/j.jposna.2026.100434", "temi": ["LCA", "adolescenti", "ciclo mestruale", "biomeccanica"]}, {"dot": "gray", "j": "Cureus", "h": "Vescicole extracellulari nel ginocchio artrosico: serie di casi, nessuna prova di efficacia", "v": "Serie retrospettiva di un solo studio medico, senza controllo; nessun prodotto è approvato negli Stati Uniti per uso intra-articolare e gli autori stessi non concludono su efficacia o sicurezza.", "pmid": "42890957", "doi": "10.7759/cureus.117960", "temi": ["artrosi", "esosomi", "ortobiologici", "infiltrazioni"]}, {"dot": "gray", "j": "Acta Bioeng Biomech", "h": "Stimolazione elettrica neuromuscolare dopo il LCA: due gruppi molto piccoli", "v": "Studio su atleti operati, con gruppi troppo piccoli per giudicare un effetto; assegnazione e analisi poco descritte nell'abstract.", "pmid": "42885196", "doi": "10.37190/abb/218840", "temi": ["LCA", "riabilitazione", "stimolazione elettrica", "rientro"]}, {"dot": "gray", "j": "Diagnostics (Basel)", "h": "Asse della gamba e orientamento della caviglia: cambiamenti dopo osteotomia, in modo esplorativo", "v": "Radiografie in carico di una coorte retrospettiva; il sottogruppo operato è piccolo e confuso da procedure diverse, nessun esito clinico.", "pmid": "42882320", "doi": "10.3390/diagnostics16193165", "temi": ["osteotomia", "allineamento", "radiografia in carico", "caviglia"]}, {"dot": "gray", "j": "J Exp Orthop", "h": "Malnutrizione e sarcopenia peggiorano gli esiti delle protesi di anca e ginocchio", "v": "Revisione sistematica di studi osservazionali su anca e ginocchio insieme; è un'associazione, non prova che correggere la nutrizione cambi l'esito.", "pmid": "42890298", "doi": "10.1002/jeo2.70657", "temi": ["protesi", "nutrizione", "sarcopenia", "fragilità"]}, {"dot": "gray", "j": "Acta Anaesthesiol Scand", "h": "Protesi di ginocchio: anestesia spinale o generale, il tempo in sala non cambia", "v": "RCT di anestesiologia su risorse e costi; non riguarda l'esito chirurgico, solo l'organizzazione.", "pmid": "42888476", "doi": "10.1111/aas.70359", "temi": ["protesi totale", "anestesia", "costi", "sala operatoria"]}, {"dot": "gray", "j": "J Appl Biomech", "h": "Salto su una gamba: le prove ripetute modificano la meccanica articolare", "v": "Studio su volontari sani, non operati; interessa a chi usa il salto come criterio di rientro dopo il LCA, ma non misura pazienti.", "pmid": "42887884", "doi": "10.1123/jab.2026-0051", "temi": ["test di salto", "criteri di rientro", "LCA", "biomeccanica"]}];
var SCOPERTE=[{"t": "Il peptide BPC-157, popolare fra gli atleti: la revisione trova solo tre studi sull'uomo, di qualità scarsa", "v": "Tre studi e trenta persone in tutto, di cui uno retrospettivo sulle infiltrazioni intra-articolari per il dolore al ginocchio; certezza dell'evidenza giudicata molto bassa e invito a non usarlo fuori da studi clinici regolati. Vale la deviazione perché i pazienti lo trovano online e lo citano; è un campo adiacente, la farmacologia non regolata.", "pmid": "42885452", "doi": "10.52628/92.3.15837", "temi": ["BPC-157", "peptidi", "atleti", "farmacologia"]}, {"t": "Un ginocchio robotico con legamenti, ispirato all'anatomia: il campo di movimento si avvicina a quello umano", "v": "Articolazione per robot biofedeli con condili sferici e legamenti collaterali disposti secondo l'anatomia, verificata su un banco robotico con tendini motorizzati. Vale la deviazione perché mostra come la bioingegneria modella il ruolo dei legamenti; non c'è alcun paziente né scopo clinico.", "pmid": "42838085", "doi": "10.1088/1748-3190/aeb0ea", "temi": ["bioingegneria", "legamenti", "robotica", "cinematica"]}, {"t": "Cattura del movimento senza marcatori dopo protesi: una telecamera a profondità contro l'analisi del cammino di laboratorio", "v": "Venti pazienti con protesi di anca o ginocchio: l'accordo fra Azure Kinect e analisi 3D di riferimento è buono per velocità e cadenza, meno per flessione massima del ginocchio. Vale la deviazione perché porta la misura del cammino dal laboratorio all'ambulatorio; è una validazione preliminare, non uno studio di esito.", "pmid": "42884402", "doi": "10.3390/s26196204", "temi": ["sensori", "cammino", "protesi", "intelligenza artificiale"]}];
var SOC={"1": {"video": "Ricostruzione del legamento crociato anteriore: un fascio di tendine o due? Una metanalisi di tredici studi randomizzati, pubblicata a ottobre 2026, mostra che nei primi due-quattro anni con due fasci il ginocchio ruota meno in modo anomalo, ma i punteggi funzionali non cambiano in modo percepibile; dopo quattro anni non c'è alcuna differenza.\n\nIl limite: gli studi usano soprattutto tendini della coscia e non tengono conto delle plastiche laterali.\nFonte: PubMed, PMID 42890719.", "linkedin": "Ricostruzione del LCA: fascio singolo o doppio fascio? Metanalisi di 13 RCT (Arthrosc Sports Med Rehabil, ottobre 2026; 1041 pazienti): a 24-48 mesi pivot shift positivo RR 0,60 (IC 95% 0,43-0,84; NNT 10); IKDC e Lysholm sotto la differenza minima importante; oltre 48 mesi nessuna differenza.\n\nLimiti: I² fino a 95%, hamstring prevalente, un solo RCT con tendine quadricipitale, plastica laterale non analizzata.\nFonte: PubMed, PMID 42890719.", "instagram": "Crociato anteriore: uno o due fasci di tendine?\nUna revisione di 13 studi randomizzati: nei primi anni il ginocchio ruota meno in modo anomalo con due fasci, ma dopo quattro anni i risultati sono gli stessi.\nLa scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42890719.", "pazienti": "Per ricostruire il legamento crociato anteriore si può usare un solo fascio di tendine oppure due. Una revisione di 13 studi randomizzati, pubblicata a ottobre 2026, mostra che nei primi anni con due fasci il ginocchio ruota meno in modo anomalo, ma il funzionamento percepito non cambia in modo chiaro; dopo quattro anni i due metodi danno gli stessi risultati.\n\nGli studi usano soprattutto tendini della coscia: la scelta si discute con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42890719."}};
var SOCV={"1": {"video": {"chir": ["Ricostruzione del LCA a fascio singolo o a doppio fascio? Una metanalisi di tredici studi randomizzati, pubblicata su Arthroscopy, Sports Medicine and Rehabilitation a ottobre 2026, ha messo insieme millequarantuno pazienti. A ventiquattro-quarantotto mesi il doppio fascio riduce il rischio di pivot shift positivo: rischio relativo zero virgola sessanta, intervallo di confidenza dal quarantatré all'ottantaquattro per cento, un paziente ogni dieci da trattare.", "Ma i punteggi IKDC e Lysholm restano sotto la differenza minima clinicamente importante, la traslazione anteriore non cambia, e oltre i quarantotto mesi non c'è alcuna differenza, né nel pivot shift né nel fallimento dell'innesto. L'eterogeneità sui punteggi arriva al novantaquattro-novantacinque per cento.", "Il limite: quasi tutti gli innesti sono hamstring, un solo studio usa il tendine quadricipitale, e la plastica laterale non è stata analizzata, anche se gli autori la indicano come possibile confondente. Per la pratica: un vantaggio rotatorio a medio termine, senza prova di un vantaggio funzionale duraturo.\nFonte: PubMed, PMID 42890719."], "misto": ["Quando si ricostruisce il legamento crociato anteriore, si può ricostruire un solo fascio di fibre oppure due. Una metanalisi di tredici studi randomizzati, pubblicata a ottobre 2026, ha messo insieme più di mille pazienti. Nei primi due-quattro anni con due fasci il ginocchio ruota meno in modo anomalo: il test di instabilità rotatoria resta positivo in circa quindici pazienti su cento contro ventisei.", "Ma i punteggi che il paziente riferisce non cambiano in modo che lo senta, e dopo quattro anni non c'è più alcuna differenza, né nella stabilità né nelle rotture dell'innesto.", "Il limite: gli studi usano soprattutto tendini della coscia e non tengono conto delle plastiche laterali aggiunte, quindi non si sa come vada con altri innesti.\nFonte: PubMed, PMID 42890719."], "pazienti": ["Per ricostruire il legamento crociato anteriore si può usare un solo fascio di tendine oppure due. Una revisione di tredici studi randomizzati, pubblicata a ottobre 2026, ha confrontato i due metodi in oltre mille pazienti.", "Nei primi due-quattro anni con due fasci il ginocchio ruota meno in modo anomalo, ma i pazienti non riferiscono un funzionamento chiaramente diverso. Dopo quattro anni i due metodi danno gli stessi risultati.", "Gli studi usano soprattutto tendini della coscia: per altri tipi di innesto non si sa. La scelta dell'intervento si discute con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42890719."]}, "linkedin": {"chir": ["Ricostruzione del LCA: fascio singolo contro doppio fascio (Arthrosc Sports Med Rehabil, ottobre 2026). Metanalisi di 13 RCT, 1041 pazienti; a 24-48 mesi pivot shift positivo RR 0,60 (IC 95% 0,43-0,84; NNT 10).", "IKDC +5,88 (IC 95% 0,44-11,33) e Lysholm +7,47 (IC 95% 0,06-14,88) sotto la differenza minima importante (11,5 e 8,9); oltre 48 mesi nessuna differenza; fallimento dell'innesto 5,5% contro 7,5% (RR 0,79; IC 95% 0,45-1,38).", "Limiti: I² 94-95% sui punteggi, hamstring prevalente, un solo RCT con tendine quadricipitale, plastica laterale non analizzata, nessuna analisi dei responder.\nFonte: PubMed, PMID 42890719."], "misto": ["Ricostruzione del legamento crociato anteriore: un fascio o due? Metanalisi di 13 studi randomizzati (ottobre 2026): nei primi 2-4 anni con due fasci il ginocchio ruota meno in modo anomalo, ma i punteggi funzionali non raggiungono una differenza percepibile.", "Dopo 4 anni nessuna differenza, né nella stabilità né nelle rotture dell'innesto.", "Limite: soprattutto tendini della coscia, plastiche laterali non considerate, un solo studio con tendine quadricipitale.\nFonte: PubMed, PMID 42890719."], "pazienti": ["Crociato anteriore: ricostruire con un fascio o con due? Una revisione di 13 studi randomizzati (ottobre 2026) mostra che nei primi anni con due fasci il ginocchio ruota meno in modo anomalo, ma il funzionamento percepito non cambia in modo chiaro.", "Dopo quattro anni i due metodi danno gli stessi risultati.", "Gli studi usano soprattutto tendini della coscia; la scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42890719."]}, "instagram": {"chir": ["LCA: fascio singolo o doppio fascio?", "13 RCT: pivot shift RR 0,60 a 24-48 mesi; nessuna differenza oltre 48 mesi.", "PROMs sotto la MCID.\nFonte: PubMed, PMID 42890719."], "misto": ["Crociato anteriore: un fascio o due?", "13 studi randomizzati: due fasci stabilizzano di più la rotazione nei primi 2-4 anni, poi nessuna differenza.", "Il vantaggio funzionale non è percepibile.\nFonte: PubMed, PMID 42890719."], "pazienti": ["Crociato anteriore: uno o due fasci di tendine?", "Nei primi anni il ginocchio ruota meno in modo anomalo con due fasci, ma dopo quattro anni i risultati sono gli stessi.", "La scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42890719."]}, "reel": {"chir": ["LCA: fascio singolo o doppio?", "RR pivot shift 0,60 a 24-48 mesi.", "Oltre 48 mesi: nessuna differenza.\nFonte: PubMed, PMID 42890719."], "misto": ["Crociato: uno o due fasci?", "Più stabilità rotatoria all'inizio, poi nessuna differenza.", "Studi soprattutto su tendini della coscia.\nFonte: PubMed, PMID 42890719."], "pazienti": ["Crociato: uno o due fasci?", "Dopo quattro anni i risultati sono gli stessi.", "Se ne parla con il chirurgo.\nFonte: PubMed, PMID 42890719."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Ginocchio #MedicinaDelloSport", "instagram": "#ortopedia #ginocchio #legamentocrociato #chirurgiadelginocchio #medicinadellosport #ortopediaticino #ticino #medicinabasatasulleprove #salute", "kw": "legamento crociato anteriore, ricostruzione, doppio fascio, fascio singolo, ginocchio"}};
var NLB={"1": {"prof": ["LCA: doppio fascio contro fascio singolo, nessuna differenza dopo 48 mesi", "Metanalisi di 13 RCT (Arthroscopy, Sports Medicine and Rehabilitation, ottobre 2026; 1041 pazienti): a 24-48 mesi il doppio fascio riduce il pivot shift positivo (RR 0,60; IC 95% 0,43-0,84; NNT 10), ma IKDC e Lysholm restano sotto la differenza minima importante e oltre i 48 mesi non ci sono differenze in alcun esito.", "Nota critica: eterogeneità alta (I² fino a 95%), quasi tutti innesti hamstring, un solo RCT con tendine quadricipitale, plastica laterale non analizzata; testo completo letto."], "mix": ["Ricostruzione del crociato con uno o due fasci: un vantaggio iniziale che dopo quattro anni non c'è più", "Una metanalisi di 13 studi randomizzati ha confrontato la ricostruzione del legamento crociato anteriore con un solo fascio e con due fasci di tendine. Nei primi due-quattro anni con due fasci il ginocchio ruota meno in modo anomalo (il test di instabilità rotatoria resta positivo in circa 15 pazienti su cento contro 26, calcolo sui numeri dello studio), ma i punteggi funzionali non cambiano in modo che il paziente lo avverta; dopo quattro anni non c'è alcuna differenza.", "Nota sul limite: gli studi usano soprattutto tendini della coscia e non tengono conto delle plastiche laterali aggiunte, quindi non si può dire come vada con altri innesti."], "paz": ["Crociato anteriore: uno o due fasci di tendine, dopo quattro anni nessuna differenza", "Per ricostruire il legamento crociato anteriore si può usare un solo fascio di tendine oppure due. Una revisione di 13 studi randomizzati mostra che nei primi anni con due fasci il ginocchio ruota meno in modo anomalo, ma il funzionamento percepito dai pazienti non cambia in modo chiaro; dopo quattro anni i due metodi danno gli stessi risultati.", "I dati vengono soprattutto da tendini della coscia: la scelta dell'intervento si discute con il chirurgo, caso per caso."], "kw": "legamento crociato anteriore, ricostruzione, doppio fascio, ginocchio"}, "2": {"prof": ["Protesi mono e totale nello stesso paziente: revisione di 10 studi, evidenza debole", "Revisione sistematica (EFORT Open Reviews, ottobre 2026; 10 studi, 437 pazienti, uno solo prospettico): KSS finale da 86,8 a 99,0 senza differenze fra monocompartimentale e totale, flessione maggiore con la monocompartimentale di 6,6°-11,2°, sopravvivenza più alta con la totale (per esempio 100% contro 85%, p=0,05).", "Nota critica: bias di indicazione (le due protesi non sono intercambiabili), periodo 1991-2024 con impianti oggi poco usati, nessuna metanalisi né intervalli di confidenza."], "mix": ["Artrosi in entrambe le ginocchia: una protesi parziale da un lato e una totale dall'altro", "Una revisione di 10 studi (437 pazienti) ha raccolto i casi in cui un ginocchio riceve una protesi parziale e l'altro una totale. I punteggi funzionali sono simili; la protesi parziale dà in genere una flessione un po' maggiore, la totale dura più spesso senza essere sostituita.", "Nota sul limite: gli studi sono quasi tutti retrospettivi e i due ginocchi non sono confrontabili, perché la protesi parziale si usa solo quando la malattia è limitata a una parte dell'articolazione."], "paz": ["Artrosi nelle due ginocchia: protesi parziale da un lato e totale dall'altro", "Quando entrambe le ginocchia sono usurate, a volte in un ginocchio basta sostituire solo la parte danneggiata e nell'altro serve una protesi totale. Una revisione di 10 studi mostra che in entrambi i casi la funzione migliora; la protesi totale tende a durare più a lungo senza dover essere rifatta.", "Gli studi sono pochi e quasi tutti retrospettivi: la scelta per ciascun ginocchio si discute con il chirurgo."], "kw": "protesi di ginocchio, protesi parziale, artrosi bilaterale, ginocchio"}, "3": {"prof": ["TKA robotica: il fenotipo coronale spiega poco del bilanciamento finale dei gap", "Coorte retrospettiva (KSSTA, ottobre 2026; 429 ginocchi): il modello con fenotipo funzionale e fattori strutturali spiega circa il 20% del gap iniziale in estensione (R² corretto 0,201) e al massimo il 6,4% del bilanciamento finale; valgo contro varo, differenza iniziale in estensione 3,10 mm (IC 95% 2,39-3,81).", "Nota critica: retrospettivo, un solo centro, nessun esito clinico; marca del robot non riportata nell'abstract."], "mix": ["Protesi totale con robot: la forma della gamba prima dell'intervento non basta a prevedere il bilanciamento", "In 429 ginocchi operati con l'aiuto di un robot, la forma della gamba misurata prima dell'intervento spiega solo in parte quanto sono tesi i legamenti all'inizio e poco quanto lo sono alla fine, dopo gli aggiustamenti. Per questo gli autori ritengono che la misura diretta durante l'intervento resti necessaria.", "Nota sul limite: è uno studio retrospettivo di un solo centro, senza esiti clinici, e non dice quale robot sia stato usato."], "paz": ["Protesi del ginocchio con robot: la tensione dei legamenti si misura durante l'intervento", "Quando il ginocchio viene operato con l'aiuto di un robot, la forma della gamba vista prima dell'intervento non basta a prevedere quanto saranno tesi i legamenti: per questo la tensione viene misurata durante l'intervento stesso.", "Lo studio non misura come stanno i pazienti dopo: descrive solo il lavoro del chirurgo in sala."], "kw": "protesi di ginocchio, chirurgia robotica, ginocchio, bilanciamento dei legamenti"}, "4": {"prof": ["Osteotomia tibiale alta aperta: esiti simili con varismo lieve e moderato a 2 anni", "Coorte retrospettiva (Frontiers in Surgery, ottobre 2026; 30 contro 30 pazienti, Kellgren-Lawrence II-III): in entrambi i gruppi migliorano allineamento, KOOS e SF-12 oltre la differenza minima importante e i gradi ICRS alla seconda artroscopia scendono; nessuna differenza significativa fra i gruppi (p>0,05).", "Nota critica: gruppi da 30, nessuna differenza non è equivalenza, nessun controllo, seconda artroscopia su un sottogruppo non descritto, slope e fissazione non riportati nell'abstract."], "mix": ["Riallineare la gamba storta: l'osteotomia dà esiti simili con curvatura lieve e moderata", "Sessanta pazienti con artrosi del lato interno del ginocchio sono stati operati di osteotomia, cioè di riallineamento della tibia. Con una curvatura della gamba lieve o moderata, in entrambi i gruppi dolore e funzione migliorano e, nelle artroscopie di controllo a due anni, la cartilagine risulta meno danneggiata.", "Nota sul limite: i gruppi sono piccoli e non c'è un confronto con chi non è stato operato, quindi non si può dire che l'intervento sia indicato anche nelle curvature più lievi."], "paz": ["Gamba leggermente storta e artrosi: l'osteotomia migliora dolore e funzione a due anni", "In un gruppo di sessanta pazienti con artrosi del lato interno del ginocchio, riallineare la tibia con un'osteotomia ha migliorato dolore e funzione a due anni, sia con una curvatura lieve sia con una moderata.", "Lo studio è piccolo e senza gruppo di confronto: se l'intervento sia adatto si valuta con il chirurgo, caso per caso."], "kw": "osteotomia tibiale alta, artrosi del ginocchio, gamba a O, ginocchio"}, "5": {"prof": ["Osteotomia tibiale alta e densità ossea: nessuna differenza a 24 mesi, ma studio senza potenza", "Coorte retrospettiva (Frontiers in Medicine, settembre 2026; 123 pazienti, 60 con osteopenia o osteoporosi): a 24 mesi VAS 0,07 (IC 95% da -0,10 a 0,24), WOMAC 1,56 (IC 95% da -3,10 a 6,22), Lysholm -0,78 (IC 95% da -2,65 a 1,09); complicanze 5,00% contro 3,17%.", "Nota critica: esplorativo, senza endpoint primario; l'intervallo sulle complicanze (RR 1,58; IC 95% 0,27-9,10) non esclude differenze rilevanti; gli stessi autori avvertono che non è prova di equivalenza."], "mix": ["Osteotomia della tibia con osso più fragile: a due anni esiti simili, ma lo studio è piccolo", "Fra 123 pazienti operati di osteotomia della tibia, quelli con osso meno denso hanno avuto dopo due anni dolore, funzione e allineamento simili a quelli con osso normale; le complicanze sono state il 5% contro il 3%.", "Nota sul limite: non si può escludere né una complicanza rara né una differenza importante, perché lo studio è retrospettivo e non abbastanza ampio per dimostrare che i due gruppi siano equivalenti."], "paz": ["Osso meno denso e osteotomia della tibia: esiti simili a due anni in uno studio piccolo", "In uno studio su 123 pazienti operati di osteotomia della tibia, chi aveva ossa meno dense ha avuto a due anni dolore e funzione simili a chi aveva ossa normali.", "Lo studio non è abbastanza ampio per escludere differenze: la valutazione dell'osso si discute con il chirurgo prima dell'intervento."], "kw": "osteotomia tibiale alta, osteoporosi, artrosi del ginocchio, ginocchio"}, "6": {"prof": ["Osteotomia derotativa sopramalleolare nel ragazzo con instabilità rotulea: serie di 21 pazienti", "Serie osservazionale (The Knee, settembre 2026; 30 ginocchia, età media 13,9 anni, follow-up medio 5,05 anni): KOOS-Child da 38,1 a 78,7 (p<0,005), Pedi-IKDC da 35,6 a 74,0, nessun reintervento per nuova lussazione.", "Nota critica: senza controllo né confronto con il solo MPFL, 21 pazienti, un fallimento clinico, rimozione dei mezzi di sintesi in metà dei casi; età media 13,9 anni, al limite del perimetro."], "mix": ["Rotula che si lussa in un ragazzo con la tibia ruotata: correggere la torsione dell'osso", "In 21 ragazzi con lussazioni ricorrenti della rotula e una torsione dell'osso della gamba, l'osteotomia che corregge la rotazione della tibia vicino alla caviglia ha portato il punteggio di funzione da circa 38 a circa 79 su 100 a cinque anni, senza nuove lussazioni che abbiano richiesto un secondo intervento.", "Nota sul limite: non c'è un gruppo di confronto e i pazienti sono pochi; metà dei pazienti ha avuto bisogno di un secondo intervento per rimuovere viti o placche."], "paz": ["Rotula che si sposta nei ragazzi: a volte il problema è la rotazione dell'osso della gamba", "In ragazzi con lussazioni ricorrenti della rotula e una gamba ruotata verso l'esterno, correggere la rotazione dell'osso vicino alla caviglia ha migliorato funzione e dolore a circa cinque anni.", "Lo studio è piccolo e senza gruppo di confronto: la scelta dell'intervento si discute con il chirurgo."], "kw": "lussazione della rotula, ginocchio, adolescenti, osteotomia"}, "7": {"prof": ["LCA all-inside con rinforzo di sutura: nessuna rottura a 2 anni in 63 pazienti, senza controllo", "Coorte retrospettiva (Orthopaedic Surgery, ottobre 2026; 19 allotrapianti e 44 autotrapianti): IKDC migliorato (p<0,001), nessuna differenza fra i tipi di innesto, 0/63 rotture (limite superiore dell'IC 95% esatto 5,7%), single leg hop sopra il 90% nel 95,2% a 12 mesi.", "Nota critica: nessun controllo e follow-up di 2 anni; tecnica e innesto diversi dai tuoi, senza plastica laterale; gli autori parlano di risultati preliminari."], "mix": ["Ricostruzione del crociato dall'interno con filo di rinforzo: nessuna rottura a due anni, ma senza confronto", "In 63 pazienti operati con una tecnica che ricostruisce il legamento crociato dall'interno del ginocchio e lo rinforza con un filo, nessun innesto si è rotto nei due anni e quasi tutti hanno ripreso una buona funzione. I risultati sono stati simili con tendine di donatore e tendine proprio.", "Nota sul limite: non c'è un gruppo di confronto, il periodo è breve e con zero rotture non si può escludere un tasso fino a circa il 6%."], "paz": ["Legamento crociato: una tecnica con rinforzo non ha mostrato rotture a due anni in uno studio piccolo", "In 63 pazienti operati al legamento crociato con una tecnica che aggiunge un filo di rinforzo, nessun legamento ricostruito si è rotto nei due anni successivi e la funzione è tornata buona.", "Lo studio è piccolo e senza gruppo di confronto: non dice se questa tecnica sia diversa dalle altre."], "kw": "legamento crociato anteriore, ricostruzione, ginocchio, rinforzo"}, "8": {"prof": ["Osteotomia fibulare prossimale: revisione di 45 studi, sintomi migliori e sicurezza non quantificata", "Revisione sistematica (The Knee, ottobre 2026; 45 studi, 2.855 ginocchia): miglioramento di dolore e funzione nella maggior parte degli studi, correzione radiografica modesta, riduzione del carico mediale nei dati biomeccanici; disfunzione transitoria del peroneo frequente, lesione permanente documentata.", "Nota critica: evidenza osservazionale, sicurezza non stimabile per segnalazione incoerente, nessuna metanalisi; non è una procedura che esegui."], "mix": ["Un taglio del perone per scaricare il lato interno del ginocchio: sintomi migliori, prove deboli", "Una revisione di 45 studi su una piccola osteotomia del perone, eseguita per scaricare la parte interna del ginocchio artrosico, trova un miglioramento di dolore e funzione, con recupero rapido. I dati sulla sicurezza sono incompleti: un disturbo transitorio del nervo peroneo è frequente e sono documentati anche danni permanenti.", "Nota sul limite: gli studi sono per lo più osservazionali e senza gruppo di controllo, quindi non si può stimare quanto spesso accadano le complicanze gravi."], "paz": ["Artrosi del lato interno del ginocchio: un taglio del perone dà sollievo, ma le prove sono deboli", "Una revisione di 45 studi su un intervento che taglia l'osso del perone, per scaricare la parte interna del ginocchio, riporta meno dolore e recupero rapido. Un disturbo temporaneo di un nervo della gamba è frequente.", "Gli studi non hanno gruppi di confronto sufficienti: se questo intervento sia adatto si valuta con il chirurgo."], "kw": "osteotomia del perone, artrosi del ginocchio, ginocchio, dolore"}, "9": {"prof": ["Condroplastica rotulea isolata: punteggi migliorati già a 3 mesi, serie retrospettiva di 39 pazienti", "Serie di casi (Arthroscopy, Sports Medicine and Rehabilitation, ottobre 2026; livello IV): tutti gli esiti migliorano da 3 mesi (p<0,001, esclusi VR-12 mentale e Marx) e restano a 12 mesi; KOOS dolore PASS 32/39 (82,1%; IC 95% di Wilson 67,3-91,0%).", "Nota critica: nessun controllo, quindi storia naturale e riabilitazione non sono separabili; nessun predittore di mancato PASS; non è la tua chirurgia cartilaginea."], "mix": ["Dolore davanti al ginocchio per cartilagine rotulea rovinata: la pulizia artroscopica migliora i sintomi", "In 39 pazienti con la cartilagine della rotula rovinata, la pulizia della superficie con l'artroscopio ha migliorato dolore e funzione già a tre mesi, e il miglioramento è rimasto a un anno; l'82% ha raggiunto un livello di dolore ritenuto accettabile.", "Nota sul limite: non c'è un confronto con chi non è stato operato o con la sola riabilitazione, quindi non si può attribuire il miglioramento all'intervento."], "paz": ["Cartilagine della rotula rovinata: la pulizia con l'artroscopio ha migliorato i sintomi in uno studio piccolo", "In 39 pazienti con la cartilagine della rotula consumata, la pulizia della superficie con l'artroscopio ha ridotto il dolore già dopo tre mesi, con un miglioramento che è rimasto a un anno.", "Senza un gruppo di confronto non si sa quanto del miglioramento dipenda dall'intervento: se ne parla con il chirurgo."], "kw": "cartilagine della rotula, condromalacia, artroscopia, ginocchio"}, "10": {"prof": ["Aspirato di midollo osseo e BMAC: 21 RCT, benefici incostanti e dipendenti dall'indicazione", "Revisione sistematica di RCT (Frontiers in Surgery, ottobre 2026; 21 RCT dal 2015 al 2025): miglioramento generale di dolore e funzione, superiorità sui comparatori incostante; segnali di beneficio nell'artrosi iniziale del ginocchio e nella patologia cartilaginea focale.", "Nota critica: sintesi narrativa su condizioni molto diverse, nessuna stima pooled, preparazione del concentrato non riportata nell'abstract."], "mix": ["Cellule del midollo osseo iniettate o impiantate: miglioramenti generali, ma risultati variabili", "Una revisione di 21 studi randomizzati ha valutato l'uso di cellule prelevate dal midollo osseo del paziente per il ginocchio, la spalla e altre sedi. Dolore e funzione migliorano in genere, ma il vantaggio rispetto alle alternative cambia da studio a studio; i segnali più chiari riguardano l'artrosi iniziale del ginocchio e i difetti di cartilagine.", "Nota sul limite: condizioni, preparazioni e confronti molto diversi fra gli studi, quindi non c'è un numero unico su cui fare affidamento."], "paz": ["Cellule del midollo osseo per il ginocchio: risultati variabili da studio a studio", "Una revisione di 21 studi ha valutato l'uso di cellule prelevate dal midollo osseo del paziente per il ginocchio e altre articolazioni. In genere dolore e funzione migliorano, ma il vantaggio rispetto ad altre terapie non è costante.", "Gli studi sono molto diversi fra loro: la scelta di un trattamento con cellule si discute con il chirurgo, caso per caso."], "kw": "midollo osseo, cellule staminali, artrosi del ginocchio, cartilagine"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Arthrosc Sports Med Rehabil",h:"LCA: il doppio fascio riduce il pivot shift a 2-4 anni, non cambia la funzione",v:"Metanalisi di 13 RCT (1041 pazienti; 536 fascio singolo, 505 doppio fascio) sul confronto fra le due ricostruzioni anatomiche, follow-up da 24 a 122 mesi, testo completo aperto. A 24-48 mesi il doppio fascio riduce il rischio di pivot shift positivo (RR 0,60; IC 95% 0,43-0,84; NNT 10), ma IKDC (+5,88 punti; IC 95% 0,44-11,33) e Lysholm (+7,47; IC 95% 0,06-14,88) restano sotto la differenza minima clinicamente importante (11,5 e 8,9). Oltre i 48 mesi nessuna differenza in nessun esito; il fallimento dell'innesto non cambia (5,5% contro 7,5%; RR 0,79; IC 95% 0,45-1,38).",ax:"Gutierrez-Moreno, Arámbula-Torres, Prieto-Baeza, Leal-Contreras, Fuentes-Flores, Berumen-Nafarrate",date:"ott 2026",meta:"metanalisi di 13 RCT, 1041 pazienti (536 fascio singolo, 505 doppio fascio), follow-up 24-122 mesi · [livello I dichiarato]",pmid:'42890719',doi:'10.1002/ars2.70102',journal:"Arthroscopy, sports medicine, and rehabilitation",authors:"Gutierrez-Moreno MA, Arámbula-Torres LE, Prieto-Baeza RA, Leal-Contreras C, Fuentes-Flores CA, Berumen-Nafarrate E",design:"Revisione sistematica con metanalisi (PROSPERO CRD420251056585; PubMed, Embase e Cochrane, 2013-settembre 2025) di RCT che confrontano la ricostruzione anatomica a fascio singolo e a doppio fascio con almeno 24 mesi di follow-up; esclusi revisioni, multilegamentose, età sotto i 16 anni. Effetti casuali (DerSimonian-Laird) per gli esiti continui, Mantel-Haenszel a effetti fissi per i dicotomici, stratificati a priori per follow-up (24-48 contro oltre 48 mesi); GRADE e rischio di bias Cochrane (basso in 5 studi, moderato in 7, alto in 1). Letto il testo completo (PMC, accesso aperto).",pop:"13 RCT di 11 paesi, 1041 pazienti analizzati, età media 30,2 anni, 68% uomini. Innesto: hamstring esclusivo in 8 studi (il testo dice 9), allotrapianto in 2, tendine quadricipitale in 1 (Irrgang, 51 pazienti), misto in 2; tunnel femorale del fascio singolo con portale anteromediale in 10 studi e transtibiale in 3. Plastica laterale (LET/ALL) non estratta.",results:"Pivot shift positivo a 24-48 mesi (6 studi, 582 pazienti): RR 0,60 (IC 95% 0,43-0,84; p=0,003; I² 61%; 43 eventi contro 75; NNT 10; GRADE moderato); oltre 48 mesi RR 1,12 (IC 95% 0,73-1,70). Traslazione anteriore a 24-48 mesi: differenza -0,34 mm (IC 95% da -1,04 a 0,35; I² 89%). IKDC soggettivo +5,88 (IC 95% 0,44-11,33; I² 94%; soglia 11,5) e Lysholm +7,47 (IC 95% 0,06-14,88; I² 95%; soglia 8,9); oltre 48 mesi IKDC -1,06 (IC 95% da -4,20 a 2,08) e Lysholm +1,02 (IC 95% da -1,85 a 3,89). Rientro allo stesso livello RR 1,08 (IC 95% 0,89-1,32; 44,9% contro 44,7%); fallimento dell'innesto RR 0,79 (IC 95% 0,45-1,38; 5,5% contro 7,5%). Escludendo l'unico studio con allotrapianto nell'analisi funzionale la significatività svanisce: IKDC +3,57 (IC 95% da -2,04 a 9,19) e Lysholm +4,39 (IC 95% da -1,01 a 9,79).",concl:"Gli autori: il doppio fascio migliora la stabilità rotatoria a 24-48 mesi e i punteggi funzionali in misura inferiore alla soglia clinica, senza differenze oltre i 48 mesi; l'evidenza attuale non sostiene un vantaggio universale del doppio fascio e la scelta dipende dalle richieste di attività del paziente e dall'esperienza del chirurgo.",limits:"Eterogeneità alta sui punteggi (I² 94-95%) · nessuno dei 13 RCT riporta il grado del pivot shift né la quota di pazienti che raggiunge la differenza minima importante, quindi niente analisi dei responder · la plastica laterale extra-articolare, che affronta la stessa instabilità rotatoria, non è stata estratta: gli autori la indicano come possibile confondente nei lavori recenti · un solo RCT con tendine quadricipitale · bias di pubblicazione non valutabile (meno di 10 studi per esito).",perte:"Arancione perché mette in discussione, per la sola stabilità rotatoria, il fascio singolo che esegui. Ma il campione è quasi tutto hamstring: un solo RCT usa il tendine quadricipitale (51 pazienti) e la plastica laterale che aggiungi a tutti i tuoi LCA non è stata analizzata; gli autori stessi ipotizzano che la tenodesi laterale pareggi nel tempo la stabilità rotatoria fra i due approcci, ma è un'ipotesi, non un risultato. Un doppio fascio con tendine quadricipitale e Lemaire onlay non è stato studiato. Cosa fare: nulla da cambiare nella tecnica; se un collega cita la metanalisi, i tre numeri sono pivot shift RR 0,60 a 24-48 mesi (NNT 10), punteggi funzionali sotto la soglia clinica, nessuna differenza dopo 48 mesi. Tocca la tensione 1 solo di sfondo."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"EFORT Open Rev",h:"Protesi mono e totale nello stesso paziente: fattibile, ma evidenza debole",v:"Revisione sistematica (EFORT Open Reviews, ottobre 2026) di 10 studi e 437 pazienti con artrosi bilaterale operati di protesi monocompartimentale da un lato e totale dall'altro: un solo studio prospettico, nove retrospettivi. Il Knee Society Score finale va da 86,8 a 99,0 senza differenze significative fra le due; la flessione favorisce la monocompartimentale di 6,6°-11,2°; la sopravvivenza è più alta con la totale (per esempio 100% contro 85%, p=0,05, nello studio prospettico). Nessuna metanalisi.",ax:"Legnani, Fadel, D'Ambrosi, Peretti, Ventura",date:"ott 2026",meta:"revisione sistematica, 10 studi (1 prospettico, 9 retrospettivi), 437 pazienti, sintesi narrativa · [qualità MINORS mediana 16/24]",pmid:'42825407',doi:'10.1530/EOR-2025-0193',journal:"EFORT open reviews",authors:"Legnani C, Fadel K, D'Ambrosi R, Peretti GM, Ventura A",design:"Revisione sistematica PRISMA (PROSPERO CRD420251027722; PubMed, Scopus, CINAHL; ricerca dell'8 dicembre 2024) di studi di qualunque livello, con almeno 6 mesi di follow-up, su pazienti con artrosi bilaterale operati di protesi monocompartimentale (UKA) e totale (TKA); 4.511 risultati, 10 studi inclusi (1991-2024). Qualità con MINORS (da 12 a 21 su 24, mediana 16), sintesi solo narrativa. Letto il testo completo (PMC, accesso aperto).",pop:"437 pazienti, età media da 61,2 a 74,0 anni, in maggioranza donne, BMI da 24,3 a 30,6; intervento a due tempi nell'83,8% (366 pazienti), simultaneo in 71 (studio di Xu); UKA a menisco mobile in 4 studi, fisso in 5, entrambi in 1; TKA a conservazione del crociato in 5 studi e posteriore stabilizzata in 5. Follow-up da 12 mesi a 11,2 anni.",results:"KSS postoperatorio da 86,8 a 99,0 in sei studi, senza differenze significative fra UKA e TKA; Forgotten Joint Score più alto con la UKA in due studi (p=0,01 e p<0,001; per esempio 97,0 ± 3,3 contro 94,9 ± 3,3 nello studio di Pongcharoen); flessione a favore della UKA di 6,6°-11,2°. Sopravvivenza con la TKA al 100% contro la UKA all'85% (Costa, p=0,05), 96% (Laurencin), 92,1% (Ma) e 95% (Sessa); 15 revisioni da UKA a TKA (usura del polietilene, mobilizzazione asettica, progressione laterale). Confronto diretto fra intervento simultaneo e a due tempi (123 pazienti, Xu): complicanze e revisioni senza differenza significativa, degenza e costi minori con il simultaneo. Intervalli di confidenza non riportati; nessuna metanalisi.",concl:"Gli autori: UKA e TKA nello stesso paziente appaiono una strategia sicura ed efficace in casi selezionati; la UKA ha più spesso flessione migliore, tempi operatori e degenza più brevi, la TKA sopravvivenza più costante e meno revisioni; servono studi prospettici e randomizzati.",limits:"Studi quasi tutti retrospettivi, piccoli, con esiti eterogenei · bias di indicazione: UKA e TKA non sono intercambiabili, le differenze riflettono anche il grado di malattia · periodo lungo (1991-2024) con impianti oggi poco usati, come il tibiale tutto polietilene · nessun intervallo di confidenza né metanalisi.",perte:"Verde: riguarda due tue procedure, la protesi monocompartimentale e la totale. Tra gli autori compare un D'Ambrosi R (Galeazzi, Milano; nome identico al riferimento che segui sull'innesto quadricipitale, identità non verificata sulle afferenze). Il dato utile per un paziente con artrosi bilaterale: la scelta del tipo di protesi per ciascun ginocchio è legittima, ma in alcuni studi la sopravvivenza della monocompartimentale è più bassa e le revisioni più frequenti; non c'è nessun RCT. Non tocca le tensioni. Cosa fare: nulla da cambiare; nel colloquio con un paziente bilaterale riportare la differenza di sopravvivenza come dato osservazionale."},{n:3,mono:"m-kssta",dot:"green",sec:"res",j:"KSSTA",h:"TKA robotica: il fenotipo coronale spiega poco dell'equilibrio finale dei gap",v:"Coorte retrospettiva (Hospital for Special Surgery, New York) su 429 TKA assistite da robot: il fenotipo coronale preoperatorio e il rimodellamento strutturale spiegano circa il 20% della variabilità del gap iniziale in estensione (R² corretto 0,201) e al massimo il 6,4% del bilanciamento finale (R² corretto 0,064). I ginocchi in valgo partono con un gap laterale più largo di circa 3 mm rispetto ai varo (3,10 mm; IC 95% 2,39-3,81). Gli autori concludono che serve la valutazione diretta intraoperatoria.",ax:"Morita, Mylonakis, Shin, El-Hassan, Shichman, Kenanidis, Tsiridis, Sculco",date:"ott 2026",meta:"coorte retrospettiva, 429 ginocchi (389 nelle analisi finali), TKA robotica · [livello III dichiarato]",pmid:'42868008',doi:'10.1002/ksa.70648',journal:"Knee surgery, sports traumatology, arthroscopy",authors:"Morita Y, Mylonakis N, Shin J, El-Hassan M, Shichman I, Kenanidis E, Tsiridis E, Sculco PK",design:"Coorte retrospettiva (livello III dichiarato) di ginocchi operati con TKA assistita da robot. Fenotipo preoperatorio con HKA, aHKA, fenotipo funzionale del ginocchio (FKP) e componenti categoriali aHKA-obliquità della rima; fattori strutturali: osteofiti mediali e laterali, sublussazione coronale. Gap mediali e laterali e range di lassità registrati in estensione e flessione prima e dopo il bilanciamento. Regressione lineare multivariata corretta per età, sesso e BMI, errori standard robusti per paziente, correzione FDR di Benjamini-Hochberg. Letto l'abstract su PubMed; testo non in PMC. L'abstract non riporta la marca del robot né il periodo.",pop:"429 ginocchi nell'analisi iniziale e 389 in quelle finali e di variazione (Complex Joint Reconstruction Center, Hospital for Special Surgery, New York). Età, sesso, BMI, marca del robot e filosofia di allineamento: non riportati nell'abstract.",results:"R² corretto del modello con fenotipo funzionale e fattori strutturali: 0,201 per il gap iniziale in estensione (esito primario) e 0,125 in flessione, quindi circa l'80% della variabilità resta non spiegata; sugli esiti finali il massimo R² corretto è 0,064. Per la variazione fra gap iniziale e finale: 0,234 con il solo fenotipo funzionale e 0,122 con il solo HKA. Ginocchi in valgo contro varo (analisi esplorativa): differenza di gap laterale meno mediale iniziale 3,10 mm in estensione (IC 95% 2,39-3,81) e 2,98 mm in flessione (IC 95% 2,23-3,74), p corretti per FDR sotto 0,001.",concl:"Gli autori: il fenotipo coronale e il rimodellamento strutturale spiegano solo in parte il bilanciamento iniziale e poco quello finale, soprattutto in flessione; i dati sostengono la valutazione diretta intraoperatoria.",limits:"Retrospettivo, un solo centro · modelli di associazione, nessun esito clinico (dolore, funzione, sopravvivenza) · marca del robot, tecnica di allineamento e di bilanciamento non riportate nell'abstract · il confronto valgo contro varo è esplorativo.",perte:"Verde: tocca la protesi totale robotica. L'abstract non dice quale robot sia stato usato, quindi non so se vale per il tuo VELYS (NON VERIFICATO). Cosa significa: la forma preoperatoria della gamba non ti dice dove finirà il bilanciamento, e i gap vanno misurati in sala. Non cambia la tua pratica e non tocca le tensioni."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Front Surg",h:"Osteotomia tibiale alta aperta: esiti simili con varismo lieve e moderato a due anni",v:"Coorte retrospettiva di Tianjin: 60 pazienti con artrosi mediale (Kellgren-Lawrence II-III) operati di osteotomia tibiale alta di apertura mediale, 30 con varismo lieve (HKA da 0° a 5°) e 30 con varismo moderato (da 5° a 10°), follow-up minimo di due anni. In entrambi i gruppi migliorano allineamento, spazio articolare mediale, KOOS e SF-12 oltre la differenza minima importante, e alla seconda artroscopia i gradi ICRS scendono; fra i gruppi nessuna differenza significativa (p>0,05).",ax:"Ren, Meng, Zhang, Li, Zhao, Wang, Huang, Cao",date:"ott 2026",meta:"coorte retrospettiva, 60 pazienti (30 contro 30), follow-up minimo 2 anni · [livello non dichiarato; retrospettivo senza controllo]",pmid:'42890041',doi:'10.3389/fsurg.2026.1942837',journal:"Frontiers in surgery",authors:"Ren F, Meng B, Zhang Z, Li W, Zhao D, Wang R, Huang J, Cao J",design:"Analisi retrospettiva di pazienti con artrosi mediale monocompartimentale (Kellgren-Lawrence II-III) operati di osteotomia tibiale alta di apertura mediale fra gennaio 2019 e gennaio 2021, follow-up minimo 2 anni, divisi per HKA preoperatorio in varismo lieve (0°<HKA<5°) e moderato (5°≤HKA<10°). Valutazioni radiografiche, artroscopiche (seconda artroscopia a 2 anni, gradi ICRS) e cliniche (SF-12, KOOS). Letto l'abstract su PubMed; testo in PMC, non aperto.",pop:"60 pazienti: 30 con varismo lieve (età media 57 ± 6 anni) e 30 con moderato (58 ± 5 anni); Tianjin Hospital, Cina. Sesso, tipo di fissazione, correzione di slope, procedure concomitanti e perdite al follow-up: non riportati nell'abstract.",results:"In entrambi i gruppi variazioni significative di HKA e rapporto della linea di carico e aumento dello spazio articolare mediale (p<0,05); spostamento verso gradi Kellgren-Lawrence più bassi a 2 anni e verso gradi ICRS più bassi alla seconda artroscopia; KOOS e SF-12 migliorati oltre la differenza minima importante. Fra i gruppi nessuna differenza significativa nei punteggi postoperatori (p>0,05). Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: l'osteotomia di apertura mediale ha dato esiti favorevoli a breve termine in pazienti selezionati con varismo lieve o moderato, senza differenze fra i gruppi; servono altri studi comparativi per stabilirne l'efficacia nel varismo lieve.",limits:"Trenta pazienti per gruppo: «nessuna differenza» non è equivalenza · retrospettivo, senza gruppo di controllo non operato · la seconda artroscopia riguarda solo chi l'ha avuta e la selezione non è descritta · follow-up di 2 anni, nessun dato su sopravvivenza o conversione a protesi nell'abstract.",perte:"Verde: riguarda le tue osteotomie. Il dato utile: nel varismo lieve (HKA da 0° a 5°) la correzione ha dato esiti analoghi al moderato, ma con numeri che non permettono di dire se sia indicata in quel gruppo. L'abstract non riporta la correzione di slope né il tipo di fissazione, quindi non è trasferibile alla tua pratica sulle correzioni di slope (NON VERIFICATO). Non cambia nulla e non tocca le tensioni."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Front Med",h:"Osteotomia tibiale alta e osso osteopenico: nessuna differenza a 2 anni, ma lo studio è muto",v:"Coorte retrospettiva di Pechino: 123 pazienti con artrosi in varo operati di osteotomia tibiale alta di apertura mediale, 60 con osteopenia (42) o osteoporosi (18) alla DXA e 63 con massa ossea normale. A 24 mesi nessuna differenza significativa per VAS (differenza 0,07; IC 95% da -0,10 a 0,24), WOMAC (1,56; IC 95% da -3,10 a 6,22), Lysholm (-0,78; IC 95% da -2,65 a 1,09) né per gli angoli radiografici, pendenza tibiale posteriore compresa. Gli autori avvertono che l'assenza di differenza non è equivalenza.",ax:"Xue, Li, Huang, Zhou, Hu, Tian",date:"set 2026",meta:"coorte retrospettiva, 123 pazienti (60 con osteopenia o osteoporosi, 63 con osso normale), follow-up 24 mesi · [livello non dichiarato; analisi esplorativa]",pmid:'42876614',doi:'10.3389/fmed.2026.1922205',journal:"Frontiers in medicine",authors:"Xue Z, Li X, Huang Y, Zhou D, Hu Y, Tian X",design:"Coorte retrospettiva (gennaio 2019-gennaio 2024) di pazienti con artrosi in varo operati di osteotomia tibiale alta di apertura mediale, classificati con DXA preoperatoria (T-score sotto -1,0 per osteopenia o osteoporosi). Esiti: VAS, WOMAC, Lysholm; MPTA, FTA, HKA, rapporto della linea di carico e pendenza tibiale posteriore fino a 24 mesi. Nessun endpoint primario né calcolo del campione: tutte le analisi sono dichiarate esplorative. Letto l'abstract su PubMed; testo in PMC, non aperto.",pop:"123 pazienti: 60 con osteopenia (42) o osteoporosi (18) e 63 con massa ossea normale; Dipartimento di articolazione minimamente invasiva, Terzo Ospedale Affiliato, Università di Medicina Cinese di Pechino. Età, sesso, tipo di fissazione e correzione ottenuta: non riportati nell'abstract.",results:"A 24 mesi nessuna differenza significativa (p>0,05) per VAS, WOMAC, Lysholm, MPTA, FTA, HKA, rapporto della linea di carico e pendenza tibiale posteriore. Differenze medie non aggiustate (osteopenia o osteoporosi meno osso normale): VAS 0,07 (IC 95% da -0,10 a 0,24), WOMAC 1,56 (IC 95% da -3,10 a 6,22), Lysholm -0,78 (IC 95% da -2,65 a 1,09). Esiti buoni o eccellenti (classificazione degli autori) 88,33% contro 90,48%; complicanze 5,00% contro 3,17% (3/60 contro 2/63; RR grezzo 1,58, IC 95% 0,27-9,10, calcolo mio con test/potenza.py).",concl:"Gli autori: osteopenia e osteoporosi non risultano associate a esiti clinici o radiografici peggiori a 24 mesi, ma l'assenza di differenza significativa non va letta come equivalenza e lo studio non ha potenza per escludere differenze rilevanti o complicanze rare.",limits:"Retrospettivo, esplorativo, senza calcolo del campione · intervallo molto largo sulle complicanze rare (RR da 0,27 a 9,10) · gruppi non randomizzati · follow-up di 24 mesi · fissazione e correzione non descritte nell'abstract.",perte:"Verde: riguarda le tue osteotomie e misura anche la pendenza tibiale posteriore. Lo studio non può dire che l'osso osteopenico sia sicuro: l'intervallo sulle complicanze non esclude né una riduzione fino a RR 0,27 né un aumento fino a RR 9,10. Cosa fare: per un paziente con densità ossea ridotta non usare questo lavoro come prova di sicurezza; resta un'indicazione da discutere caso per caso. Non tocca le tensioni."},{n:6,mono:"m-knee",dot:"green",sec:"res",j:"The Knee",h:"Osteotomia derotativa sopramalleolare nei ragazzi con instabilità rotulea e torsione tibiale",v:"Serie osservazionale di Sheffield: 30 ginocchia in 21 pazienti (età media 13,9 anni) con instabilità rotulea ricorrente o dolore anteriore e torsione di tibia e femore, operati di osteotomia derotativa sopramalleolare della tibia (estorsione media 49,1 ± 5,24°), con o senza stabilizzazione rotulea. A 5,05 anni di follow-up medio KOOS-Child da 38,1 a 78,7 (p<0,005), Pedi-IKDC da 35,6 a 74,0, Kujala da 35,9 a 73,0; nessun reintervento per nuova lussazione, un fallimento clinico.",ax:"Dalal, Denton, Stanier, Nicolaou",date:"set 2026",meta:"serie osservazionale con raccolta prospettica, 30 ginocchia in 21 pazienti, follow-up medio 5,05 anni · [senza controllo]",pmid:'42815203',doi:'10.1016/j.knee.2026.104644',journal:"The Knee",authors:"Dalal N, Denton M, Stanier P, Nicolaou N",design:"Studio osservazionale con raccolta dati prospettica in 10 anni (Sheffield Children's Hospital) su pazienti con lussazione rotulea ricorrente o dolore anteriore, torsione di tibia e femore ed extrarotazione dell'anca oltre 15°, operati di osteotomia derotativa tibiale singola sopramalleolare; coorte 1 con instabilità (20 ginocchia) e coorte 2 con dolore anteriore e instabilità soggettiva (10). Letto l'abstract su PubMed; testo non in PMC.",pop:"30 ginocchia in 21 pazienti, età media 13,9 anni all'intervento, follow-up medio 5,05 anni; estorsione tibiale media preoperatoria 49,1 ± 5,24° alla TC. Sesso, quota con ricostruzione del MPFL concomitante e tecnica di fissazione: non riportati nell'abstract.",results:"KOOS-Child da 38,1 a 78,7 (p<0,005 in tutte e cinque le sottoscale); Pedi-IKDC da 35,6 a 74,0; Kujala da 35,9 a 73,0. Nessun reintervento per nuova lussazione; un fallimento clinico (fisi aperta e troclea convessa) in lista per troclearplastica; rimozione dei mezzi di sintesi in metà della coorte. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: l'osteotomia derotativa tibiale distale sembra sicura e può essere considerata nei pazienti con torsione, con il potenziale di ridurre le recidive osservate dopo la sola ricostruzione del MPFL.",limits:"Nessun gruppo di controllo né confronto con il solo MPFL · 21 pazienti, pochi per giudicare le recidive rare · raccolta in 10 anni con indicazioni e tecniche possibilmente variabili (non descritto) · metà dei pazienti reintervenuta per rimuovere i mezzi di sintesi.",perte:"Verde: tocca il tuo MPFL (ancore FiberTak, onlay) per l'indicazione, non per la tecnica. L'età media è 13,9 anni, appena sotto il tuo perimetro (dai 14). Non è un confronto: «la sola ricostruzione del MPFL ha recidive elevate» è la premessa degli autori, non un risultato di questo lavoro. Utile come criterio: nei pazienti con torsione tibiale marcata valutare la torsione alla TC prima di decidere solo sul MPFL; non cambia la tua tecnica. Non tocca le tensioni."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Orthop Surg",h:"LCA all-inside con rinforzo di sutura: nessuna rottura a 2 anni in 63 pazienti, senza controllo",v:"Coorte retrospettiva malese da registro (63 pazienti, 19 allotrapianti e 44 autotrapianti) con la tecnica UKM Internal Bracing modificata: ricostruzione all-inside più rinforzo con sutura. A 24 mesi IKDC migliorato (p<0,001), nessuna differenza fra allotrapianto e autotrapianto, nessuna rottura dell'innesto (0/63; limite superiore dell'IC 95% esatto 5,7%, calcolo mio) e single leg hop sopra il 90% nel 95,2% a 12 mesi. Gli autori stessi parlano di risultati preliminari e generatori di ipotesi.",ax:"Yusoff, Hamid, Mohamad, Ramlan, Kamaruzman, Omar, Asikin, Azwan Aziz",date:"ott 2026",meta:"coorte retrospettiva da registro, 63 pazienti (19 allotrapianto, 44 autotrapianto), follow-up 24 mesi, senza controllo · [livello non dichiarato]",pmid:'42878690',doi:'10.1111/os.70442',journal:"Orthopaedic surgery",authors:"Yusoff BAHM, Hamid MHB, Mohamad N, Ramlan KR, Kamaruzman NKAN, Omar A, Asikin Z, Azwan Aziz M",design:"Coorte retrospettiva da registro (Universiti Kebangsaan Malaysia, Kuala Lumpur) di LCA primari isolati con tecnica all-inside e rinforzo di sutura (MUIB), 2020-2024; IKDC, VAS, rottura dell'innesto, single leg hop e complicanze a 3, 6, 12 e 24 mesi. Nessun gruppo di confronto. Letto l'abstract su PubMed; testo in PMC, non aperto.",pop:"63 pazienti: 19 allotrapianti e 44 autotrapianti (tipo di tendine, età, sesso e lesioni associate: non riportati nell'abstract).",results:"Miglioramento rispetto al preoperatorio a 2 anni in entrambi i gruppi (p<0,001); nessuna differenza significativa fra allotrapianto e autotrapianto in alcun esito; VAS 0 raggiunta entro 6 mesi in entrambi; nessuna nuova rottura dell'innesto (0/63; IC 95% esatto da 0 a 5,7%, calcolo mio) e 95,2% dei pazienti con single leg hop oltre il 90% a 12 mesi; nessuna infezione, artrofibrosi o complicanza da mezzi di sintesi con reintervento. Valori numerici dei punteggi e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: esiti molto favorevoli a 2 anni con nessun fallimento, ma disegno retrospettivo e non controllato: risultati preliminari e generatori di ipotesi; servono studi comparativi prospettici.",limits:"Nessun controllo e 63 pazienti: con zero eventi non si può escludere un tasso di rottura fino al 5,7% · follow-up di 2 anni, troppo breve per le rotture tardive · innesto, età e rischio di base non descritti · registro di un solo centro.",perte:"Bianco: è un LCA, ma con tecnica (all-inside con rinforzo di sutura) e innesti (allotrapianto o autotrapianto, tendine non specificato) diversi dai tuoi, e senza plastica laterale. Non trasferibile alla tua pratica (quadricipite e Lemaire onlay). Rinforzo con sutura e plastica laterale sono due modi diversi di proteggere l'innesto, ma qui nessun confronto. Non tocca le tensioni."},{n:8,mono:"m-knee",dot:"gray",sec:"res",j:"Knee",h:"Osteotomia fibulare prossimale per l'artrosi mediale: sintomi migliori, prove osservazionali",v:"Revisione sistematica PRISMA (PROSPERO CRD420261386493) con 45 studi (38 clinici e 7 biomeccanici o anatomici; 2.855 ginocchia): la maggior parte riferisce miglioramento di dolore, funzione e PROMs, con correzione radiografica modesta e spazio articolare mediale aumentato; gli studi biomeccanici mostrano meno carico mediale con ridistribuzione laterale. Disfunzione transitoria del nervo peroneo comune frequente, danni neurologici permanenti documentati, incidenza delle complicanze gravi incerta.",ax:"Edmonds, Duru, Olamona, Soni, McDonnell, Radhamony",date:"ott 2026",meta:"revisione sistematica, 45 studi (38 clinici, 7 biomeccanici o anatomici), 2.855 ginocchia, sintesi narrativa · [prevalentemente osservazionale]",pmid:'42880209',doi:'10.1016/j.knee.2026.104653',journal:"The Knee",authors:"Edmonds CJ, Duru D, Olamona VB, Soni D, McDonnell SM, Radhamony N",design:"Revisione sistematica PRISMA 2020 (MEDLINE, Scopus, Web of Science, Cochrane, CNKI, dall'origine a maggio 2026) di studi clinici sulla osteotomia fibulare prossimale (PFO) nell'artrosi mediale e di studi biomeccanici, su cadavere e anatomici; rischio di bias con RoB 2 e Newcastle-Ottawa; per l'eterogeneità solo sintesi narrativa. Letto l'abstract su PubMed; testo non in PMC.",pop:"45 studi, 2.855 ginocchia con artrosi del compartimento mediale. Età, grado di artrosi, deformità e follow-up: non riportati nell'abstract.",results:"Miglioramento di dolore, funzione e PROMs nella maggior parte degli studi; correzione radiografica modesta con aumento dello spazio articolare mediale, mentre il sollievo dei sintomi supera spesso la correzione; tempi operatori e degenza brevi, perdita di sangue bassa. Disfunzione transitoria del peroneo comune frequente, lesione permanente documentata, incidenza delle complicanze gravi incerta per segnalazione incoerente. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la PFO si associa a miglioramento dei sintomi con recupero rapido, e i dati biomeccanici sostengono un meccanismo di modifica del carico, non di correzione della deformità; la fiducia nell'efficacia e nella sicurezza è limitata da evidenza osservazionale, disegni eterogenei e pochi dati comparativi a lungo termine.",limits:"Evidenza prevalentemente osservazionale, spesso senza controllo · segnalazione delle complicanze incoerente: la sicurezza non è stimabile · nessuna metanalisi, nessun intervallo di confidenza nell'abstract · testo completo non aperto.",perte:"Bianco: è un'osteotomia del ginocchio, ma non è una tua tecnica; le tue osteotomie correggono l'asse (osteotomia tibiale alta, slope). Entra perché è una procedura che i pazienti trovano online e che i colleghi possono citare, e perché gli autori dichiarano un meccanismo di scarico del carico mediale, non di correzione. Cosa fare: nulla; se un paziente la porta in visita, i dati dicono sintomi migliori a breve termine e sicurezza neurologica non quantificata. Non tocca le tensioni."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Arthrosc Sports Med Rehabil",h:"Condroplastica rotulea isolata: punteggi migliorati già a 3 mesi in 39 pazienti",v:"Serie retrospettiva da registro di un chirurgo (Mass General Brigham, livello IV): 39 pazienti (35 donne, età media 31,4 anni) con condromalacia rotulea isolata operati di condroplastica artroscopica. Tutti gli esiti migliorano a 3 mesi (p<0,001, esclusi la componente mentale del VR-12 e il Marx) e restano a 12 mesi; sul KOOS dolore lo stato accettabile (PASS) è raggiunto da 32 su 39 (82,1%; IC 95% di Wilson 67,3-91,0%, calcolo mio). Nessun fattore preoperatorio prevede chi non lo raggiunge.",ax:"Sherman, Queenan, Mazzocca, Jacobs, Matzkin",date:"ott 2026",meta:"serie di casi retrospettiva da registro, 39 pazienti, follow-up 12 mesi · [livello IV]",pmid:'42865974',doi:'10.1002/ars2.70095',journal:"Arthroscopy, sports medicine, and rehabilitation",authors:"Sherman N, Queenan K, Mazzocca JL, Jacobs CA, Matzkin EG",design:"Serie di casi retrospettiva (livello IV) da registro di un chirurgo: pazienti con condroplastica artroscopica rotulea isolata, KOOS, Single Assessment Numerical Evaluation, VAS dolore, Marx e VR-12 prima dell'intervento e a 3, 6 e 12 mesi; ANOVA a misure ripetute, quota di pazienti che raggiunge il PASS del KOOS e regressione logistica per i predittori. Letto l'abstract su PubMed; testo in PMC, non aperto.",pop:"39 pazienti con dati completi (35 donne e 4 uomini), età media 31,4 anni, BMI medio 26,5. Dimensione, grado e sede della lesione: non riportati nell'abstract.",results:"Dal basale a 3 mesi tutti gli esiti migliorano (p<0,001), salvo la componente mentale del VR-12 (p=0,33) e il Marx (p=0,11), e restano a 12 mesi. PASS a 12 mesi: dolore 32/39 (82,1%), sintomi 24/39 (61,5%), attività quotidiane 30/39 (76,9%), sport 35/39 (89,7%), qualità di vita 29/39 (74,4%). IC 95% di Wilson sul dolore 67,3-91,0% (calcolo mio). Nessun predittore preoperatorio significativo per il PASS sul dolore.",concl:"Gli autori: la condroplastica rotulea isolata dà miglioramenti significativi dei punteggi già a 3 mesi, mantenuti da gran parte dei pazienti a 12 mesi.",limits:"Nessun gruppo di controllo: storia naturale, riabilitazione ed effetto placebo non sono separabili · 39 pazienti, quasi tutte donne, con dati completi su un campione di registro più ampio · follow-up di 12 mesi · dimensione e grado della lesione non descritti nell'abstract.",perte:"Bianco: la condroplastica rotulea non è la tua chirurgia cartilaginea (AMIC con Chondro-Gide, AutoCart su difetti focali). Entra perché è l'alternativa semplice nella condropatia rotulea e perché una giovane paziente con dolore anteriore può chiedertela. Senza controllo il miglioramento non è attribuibile alla sola condroplastica. Non tocca le tensioni."},{n:10,mono:"m-gray",dot:"gray",sec:"res",j:"Front Surg",h:"Aspirato di midollo osseo: 21 RCT, benefici incostanti e dipendenti dall'indicazione",v:"Revisione sistematica PRISMA di 21 RCT (dicembre 2015-dicembre 2025) su aspirato (BMA) e concentrato (BMAC) di midollo osseo in artrosi del ginocchio, LCA, cuffia dei rotatori, difetti cartilaginei focali, osteonecrosi, lombalgia discogenica e artrosi gleno-omerale: dolore e funzione migliorano in generale, ma la superiorità sui comparatori è incostante; segnali di beneficio maggiore nell'artrosi iniziale del ginocchio, nella patologia cartilaginea focale, nelle lesioni legamentose non chirurgiche e nella cuffia.",ax:"Dias Batista, Dias Silva, Dias Batista, Santos Pereira, da Silva",date:"ott 2026",meta:"revisione sistematica di 21 RCT, sintesi narrativa, PROSPERO CRD420251241519 · [RCT eterogenei]",pmid:'42890620',doi:'10.3389/fsurg.2026.1932090',journal:"Frontiers in surgery",authors:"Dias Batista J, Dias Silva L, Dias Batista J, Santos Pereira G, da Silva ML",design:"Revisione sistematica PRISMA 2020 (PubMed, Embase, Scopus, Web of Science; dicembre 2015-dicembre 2025) di RCT che confrontano BMA o BMAC con placebo, terapie infiltrative convenzionali, esercizio o procedure chirurgiche standard; esiti: dolore, funzione, guarigione strutturale all'imaging, fallimento o revisione, sicurezza; rischio di bias con Cochrane RoB 2.0, sintesi narrativa. Letto l'abstract su PubMed; testo in PMC, non aperto.",pop:"21 RCT in adulti con patologie ortopediche diverse (ginocchio, spalla, colonna, osteonecrosi). Numerosità, preparazione del concentrato e comparatori: non riportati nell'abstract.",results:"Miglioramento generale di dolore e funzione con BMA e BMAC, ma superiorità sui comparatori incostante e dipendente dalla condizione e dalla strategia di trattamento; segnali di beneficio maggiore nell'artrosi iniziale del ginocchio, nella patologia cartilaginea focale, nelle lesioni legamentose non chirurgiche e nei disturbi della cuffia dei rotatori. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: BMA e BMAC possono migliorare dolore e funzione in pazienti selezionati, ma la superiorità sui comparatori non è costante e dipende dall'indicazione.",limits:"Sintesi solo narrativa su condizioni molto diverse: nessuna stima unica citabile · rischio di bias valutato ma i risultati non compaiono nell'abstract · preparazione del concentrato, dose e comparatori non riportati · testo completo non aperto.",perte:"Bianco: biologici per cartilagine e LCA, non una tua tecnica; l'AMIC con Chondro-Gide usa la stimolazione midollare e l'abstract non dice se gli RCT sul difetto focale impiegassero il BMAC con matrice. Entra perché i pazienti chiedono i trattamenti con cellule: la revisione non regge una raccomandazione per nessuna indicazione singola. Non tocca le tensioni (la 5 riguarda il minced cartilage, non il BMAC)."}];
var SUGGQ=[{"k": "kol", "n": "Daniel B. F. Saris (Mayo Clinic, Rochester, Minnesota)", "w": "Stati Uniti: coautore ricorrente nello storico, nelle ultime due settimane compare nei lavori di Mayo Clinic su MPFL, LCA con tendine quadricipitale e protesi dopo osteotomia (nome e afferenza letti nei metadati PubMed del PMID 42876992). Corrispondenza tecnica con la cartilagine (biopsie e impianto di condrociti, MACI) accanto a LCA e MPFL, cioè l'asse AMIC e AutoCart che esegui. Sostituisce Peter Balcarek (17 ottobre; nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Domenica 18 ottobre. Apro con la settimana, negli ultimi sei giorni. Cinque lavori contano. Il consensus UEFA sul legamento crociato anteriore nel calcio femminile: la parte due porta il rientro a criteri e non a tempi fissi, con la forza del quadricipite come tappa centrale. La serie di Chicago sul pie-crusting del collaterale mediale durante la rifissazione della radice meniscale: il valgo si apre di un millimetro e due in più, intervallo di confidenza da zero virgola settantatré a uno virgola settanta, sotto la soglia di tre virgola due. La coorte di Guangzhou sulle radici posteriori mediali: a guarigione identica alla risonanza, l'estrusione è maggiore e l'artrosi progredisce di più dopo un esordio insidioso. La revisione sulla ricostruzione del collaterale mediale, allotrapianto contro hamstring, con complicanze undici virgola due per cento contro quattro, ma confronto indiretto. E lo studio di Zagabria sulla pendenza tibiale posteriore. Le tensioni mosse: il criterio di rientro e la radice meniscale; il rinforzo laterale solo di sfondo. Oggi dieci lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo, nessuna voce nuova nelle linee guida del perimetro e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è una metanalisi di tredici studi randomizzati sulla ricostruzione del crociato anteriore a fascio singolo contro doppio fascio, ed è arancione perché mette in discussione il fascio singolo che esegui. Ho letto il testo completo. A ventiquattro-quarantotto mesi il doppio fascio riduce il rischio di pivot shift positivo, rischio relativo zero virgola sessanta, intervallo di confidenza da zero virgola quarantatré a zero virgola ottantaquattro, un paziente ogni dieci. Ma i punteggi IKDC e Lysholm restano sotto la differenza minima clinicamente importante, e dopo i quarantotto mesi non c'è alcuna differenza, né nel pivot shift né nel fallimento dell'innesto. Quasi tutti gli innesti sono hamstring, uno solo è il tendine quadricipitale, e la plastica laterale non è stata analizzata. Poi cinque lavori sulle tue tecniche. Una revisione su protesi monocompartimentale e totale nello stesso paziente, dieci studi e quattrocentotrentasette pazienti, fra gli autori un D'Ambrosi: punteggi simili, sopravvivenza più alta con la totale, evidenza debole. Una coorte di quattrocentoventinove protesi totali robotiche a New York: il fenotipo della gamba prima dell'intervento spiega poco del bilanciamento finale; non so se il robot sia il tuo. Due studi sull'osteotomia tibiale alta: trenta contro trenta pazienti con varismo lieve o moderato, esiti simili a due anni, e centoventitré pazienti con osso osteopenico o normale, senza differenze ma con un intervallo troppo largo per dire che siano equivalenti. E una serie di Sheffield sull'osteotomia derotativa della tibia in ragazzi con instabilità rotulea. Poi quattro lavori di contesto: una coorte malese sul crociato all-inside con rinforzo di sutura, nessuna rottura su sessantatré pazienti ma senza controllo; la revisione sull'osteotomia fibulare prossimale; la condroplastica rotulea isolata; e la revisione di ventuno studi randomizzati sull'aspirato di midollo osseo. Nessuna tensione si è mossa oggi, salvo una nota di sfondo sul rinforzo laterale. Nella seconda pagina undici brevi e tre proposte fuori dal solito, fra cui la revisione sul peptide BPC-157.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Domenica diciotto ottobre. Apro con la settimana. Cinque lavori contano: il consensus UEFA sul crociato nel calcio femminile, con il rientro a criteri; il pie-crusting del collaterale mediale nella rifissazione della radice meniscale, un millimetro e due di apertura in più; la coorte di Guangzhou sulle radici posteriori, dove l'esordio insidioso peggiora l'estrusione; la revisione sul collaterale mediale; e lo studio di Zagabria sulla pendenza tibiale."}, {"chi": "B", "t": "E le tensioni?"}, {"chi": "A", "t": "Si sono mossi il criterio di rientro e la radice meniscale; il rinforzo laterale solo di sfondo."}, {"chi": "B", "t": "E oggi?"}, {"chi": "A", "t": "Dieci lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Una metanalisi di tredici studi randomizzati sulla ricostruzione del crociato anteriore a fascio singolo contro doppio fascio. È arancione perché mette in discussione il fascio singolo che esegui."}, {"chi": "B", "t": "Cosa trova?"}, {"chi": "A", "t": "A ventiquattro-quarantotto mesi il doppio fascio riduce il rischio di pivot shift positivo, rischio relativo zero virgola sessanta, un paziente ogni dieci. Ma IKDC e Lysholm restano sotto la soglia clinica, e dopo quarantotto mesi non c'è differenza."}, {"chi": "B", "t": "Quindi per il mio quadricipite con il Lemaire?"}, {"chi": "A", "t": "Non cambia nulla. Quasi tutti gli innesti sono hamstring, uno solo è il quadricipite, e la plastica laterale non è stata analizzata."}, {"chi": "B", "t": "Gli altri lavori sulle mie tecniche?"}, {"chi": "A", "t": "Protesi monocompartimentale e totale nello stesso paziente: punteggi simili, sopravvivenza più alta con la totale, evidenza debole. Una coorte di protesi totale robotica a New York, dove il fenotipo della gamba spiega poco del bilanciamento finale; non so se il robot sia il tuo VELYS. Due studi sull'osteotomia tibiale alta, esiti simili a due anni ma gruppi piccoli. E una serie sull'osteotomia derotativa della tibia nei ragazzi con instabilità rotulea."}, {"chi": "B", "t": "E la seconda pagina?"}, {"chi": "A", "t": "Undici brevi e tre proposte fuori dal solito, fra cui la revisione sul peptide BPC-157."}];
